```openscad
// Pin hinge leaf
// Print orientation: flat plate on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 50;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

knuckle_d   = 7;     // knuckle cylinder diameter
knuckle_z   = 3.5;   // knuckle axis height above bed
knuckle_y   = 12.5;  // knuckle axis Y position (on +Y edge)
knuckle_n   = 5;     // number of segments along length
knuckle_pitch = plate_len / knuckle_n; // 10 mm segment length

pin_d       = 3;     // pin hole diameter
eps         = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (odd segments)
        for (i = [0 : 2 : knuckle_n - 1]) {
            x_c = -plate_len/2 + i * knuckle_pitch;
            translate([x_c - knuckle_d/2, knuckle_y, 0])
                cylinder(d = knuckle_d, h = plate_thk + 1);
        }
    }

    // Pin hole along the knuckle axis, through every knuckle
    translate([-plate_len/2 - eps, knuckle_y, 0])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}
