    // Star outline, centred on origin, first outer point on +X axis
    polygon(points = concat(
        [for (i = [0 : point_n - 1])
            rotate(i * 360 / point_n) [outer_r, 0],
            rotate(i * 360 / point_n + 180 / point_n) [inner_r, 0]],
        [[outer_r, 0]]
    ),
    // Cut central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps);
}

// ---------------- Render ----------------
