// Star-shaped indexing wheel
// Flat 5-pointed star plate with a central through-hole

// ---------- Parameters ----------
n_points   = 5;    // number of star points
r_outer    = 40;   // radius of outer (tip) points [mm]
r_inner    = 20;   // radius of inner (valley) points [mm]
thickness  = 3;    // plate thickness [mm]
hole_d     = 6;    // central hole diameter [mm]
start_ang  = 0;    // angle of first outer point (+X axis) [deg]
cut_extra  = 0.5;  // extra length for cutting shapes past faces [mm]
$fn        = 96;   // facet count for curved shapes

// ---------- Derived ----------
step = 360 / n_points;   // angle between successive outer points

// Star outline: alternating outer and inner points
star_pts = [
    for (i = [0 : 2 * n_points - 1])
        let (
            a = start_ang + i * step / 2,
            r = (i % 2 == 0) ? r_outer : r_inner
        )
        [r * cos(a), r * sin(a)]
];

// ---------- Model ----------
difference() {
    // Star plate
    linear_extrude(height = thickness)
        polygon(star_pts);

    // Central through-hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = thickness + 2 * cut_extra, $fn = 96);
}
