top_size       = 80;    // top square side length (at z = block_h)
block_h        = 30;    // overall height of the frustum
pocket_w       = 72;    // square pocket side length (top face)
pocket_depth   = 5;     // square pocket depth into top face
eps            = 0.5;   // overshoot for clean boolean cuts

$fn = 64;

// ---------- Model ----------
difference() {
    // Square frustum body
    linear_extrude(height = block_h)
        hull() {
            translate([-base_size / 2, -base_size / 2]) square(base_size);
            translate([-top_size / 2, -top_size / 2]) square(top_size);
        }

    // Pocket cut into the top face
    translate([0, 0, block_h - pocket_depth])
        cube([pocket_w, pocket_w, pocket_depth + eps]);
}
