// Print orientation: wide base on the bed (z = 0), narrowing upward

// ---------- Dimensions (mm) ----------
base_w      = 80;   // bottom square side length
base_h      = 20;   // overall height of the block
top_w       = 40;   // top square side length
pocket_w    = 30;   // square pocket side length
pocket_d    = 8;    // square pocket depth
eps         = 0.5;  // overshoot for clean boolean cuts

$fn = 64;

// ---------- Model ----------
difference() {
    // Frustum body
    linear_extrude(height = base_h)
        hull() {
            translate([-base_w / 2, -base_w / 2]) square([base_w, base_w]);
            translate([-top_w / 2, -top_w / 2]) square([top_w, top_w]);
        }

    // Square pocket in the top face
    translate([0, 0, base_h - pocket_d])
        cube([pocket_w, pocket_w, pocket_d + eps]);
}
