```openscad
// Tapered riser block (square frustum) with top pocket
// Units: mm

base_size    = 80;   // bottom square side length (z = 0)
top_size     = 40;   // top square side length (z = block_height)
block_height = 20;   // overall height of frustum

pocket_size  = 30;   // square pocket side length
pocket_depth = 8;    // pocket depth from top face

eps = 0.5;           // overshoot for clean boolean cuts

$fn = 64;

module frustum() {
    b = base_size / 2;
    t = top_size / 2;
    polyhedron(
        points = [
            [-b, -b, 0], [ b, -b, 0], [ b,  b, 0], [-b,  b, 0],              // bottom
            [-t, -t, block_height], [ t, -t, block_height],
            [ t,  t, block_height], [-t,  t, block_height]                   // top
        ],
        faces = [
            [0, 1, 2, 3],   // bottom
            [4, 5, 1, 0],   // front (-Y)
            [5, 6, 2, 1],   // right (+X)
            [6, 7, 3, 2],   // back (+Y)
            [7, 4, 0, 3],   // left (-X)
            [7, 6, 5, 4]    // top
        ]
    );
}

difference() {
    frustum();
    // square pocket in top face
    translate([-pocket_size / 2, -pocket_size / 2, block_height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
