// ---- Dimensions (mm) ----
thickness    = 5;    // overall part thickness (Z)
rim_od       = 60;   // rim outer diameter
rim_width    = 5;    // rim radial width
hub_d        = 14;   // hub outer diameter
axle_d       = 8;    // axle hole diameter
spoke_count  = 8;    // number of spokes
spoke_width  = 4;    // spoke width (tangential)
eps          = 0.5;  // cutter overshoot

// ---- Derived ----
rim_id       = rim_od - 2 * rim_width;          // rim inner diameter (50)
spoke_start  = axle_d / 2 + 1;                  // start inside hub (overlap)
spoke_end    = rim_id / 2 + rim_width / 2;      // end inside rim (overlap)

difference() {
    union() {
        // Outer rim
        difference() {
            cylinder(d = rim_od, h = thickness);
            translate([0, 0, -eps])
                cylinder(d = rim_id, h = thickness + 2 * eps);
        }

        // Hub
        cylinder(d = hub_d, h = thickness);

        // Spokes, first along +X
        for (i = [0 : spoke_count - 1])
            rotate([0, 0, i * 360 / spoke_count])
                translate([spoke_start, -spoke_width / 2, 0])
                    cube([spoke_end - spoke_start, spoke_width, thickness]);
    }

    // Axle hole through hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
}
