plate_len   = 60;    // plate length along X (mm)
plate_wid   = 25;    // plate width along Y (mm)
plate_thk   = 2.5;   // plate thickness along Z (mm)

// ---------- Knuckles ----------
n_segments  = 3;                       // number of equal segments along the edge
seg_len     = plate_len / n_segments;  // segment length (20 mm)
knuckle_d   = 8;     // knuckle outer diameter (mm)
axis_y      = 12.5;  // hinge axis Y position (mm) - on the +Y edge
axis_z      = 4;     // hinge axis Z height (mm)
knuckle_segs = [0, 2]; // segment indices that carry knuckles (1st and 3rd)

// ---------- Pin hole ----------
pin_d       = 2.5;   // pin hole diameter (mm)
eps         = 0.5;   // cutter overshoot past faces (mm)

difference() {
    union() {
        // Flat plate, centred on origin in X and Y
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the selected segments
        for (i = knuckle_segs) {
            x0 = -plate_len/2 + i * seg_len;
            translate([x0, axis_y, axis_z])
                rotate([0, 90, 0])
                    cylinder(d = knuckle_d, h = seg_len);
        }
    }

    // Pin hole along the common knuckle axis, through every knuckle
    translate([-plate_len/2 - eps, axis_y, axis_z])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = plate_len + 2*eps);
}
