difference() {
    union() {
        // Base plate
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles (overlap slightly into plate for a clean union)
        for (x = [knuckle_x0, knuckle_x2])
            translate([x - 0.01, knuckle_y, knuckle_z])
                cylinder(r = knuckle_r, h = plate_wid / 2 + 1);
    }

    // Pin holes through every knuckle along the common axis
    for (x = [knuckle_x0, knuckle_x2])
        translate([x, knuckle_y, knuckle_z])
            cylinder(d = pin_d, h = plate_wid / 2 + 2, center = true);
}
