    linear_extrude(height = plate_t)
        polygon(points = star_outline(outer_r, inner_r, n_points));

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = plate_t + 2 * eps, $fn = 128);
}

// ---------------- Helpers ----------------
// Outline of a 2m-pointed star (m = n_points / 2), first outer point on +X
function star_outline(outer_r, inner_r, m) {
    outline = [];
    for (i = [0 : m - 1]) {
        theta = i * 360 / m;
        outline.append([outer_r * cos(theta), outer_r * sin(theta)]);
        theta = (i + 0.5) * 360 / m;
        outline.append([inner_r * cos(theta), inner_r * sin(theta)]);
    }
    return outline;
}
