// Tapered riser block for setting a beaker higher
// Print orientation: wide base on the bed (z = 0), narrow top at z = 25

// ---------- Dimensions (mm) ----------
base_size      = 80;   // bottom square side length
top_size       = 40;   // top square side length
block_height   = 25;   // overall height of the frustum
pocket_size    = 32;   // square pocket side length (top face)
pocket_depth   = 5;    // square pocket depth
eps            = 0.5;  // overshoot for clean boolean cuts

$fn = 64;

// ---------- Model ----------
difference() {
    // Square frustum body
    linear_extrude(height = block_height)
        hull() {
            translate([-base_size / 2, -base_size / 2]) square(base_size);
            translate([-top_size / 2, -top_size / 2]) square(top_size);
        }

    // Square pocket in the top face
    translate([0, 0, block_height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
}
