// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---- Dimensions (mm) ----
plate_len   = 40;    // plate length along X
plate_wid   = 30;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z
knuckle_d   = 6;     // knuckle cylinder diameter
knuckle_n   = 5;     // number of knuckle segments
knuckle_h   = 5;     // knuckle height above plate (z = 3 + 2)
pin_d       = 2.5;   // pin hole diameter
eps         = 0.5;   // cutter overshoot past faces

$fn = 64;

// X position of segment i (0..knuckle_n-1), each 8 mm wide
function seg_x(i) = (i - (knuckle_n - 1) / 2) * plate_len / knuckle_n;

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (i = 0, 2, 4)
        for (i = [0 : 2 : knuckle_n - 1])
            translate([seg_x(i), plate_wid/2 - 1, plate_thk - 0.01])
                cylinder(d = knuckle_d, h = knuckle_h + 0.01);
    }

    // Pin hole along the common axis (y = 15, z = 3) through every knuckle
    for (i = [0 : 2 : knuckle_n - 1])
        translate([seg_x(i) + 0.5, plate_wid/2 - 1, 3])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = knuckle_d + 2*eps, center = true);
}
