        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on segments 1, 3, 5 (i = 1, 3, 5)
        for (i = [1, 3, 5])
            translate([seg_x(i), plate_wid/2 - 0.01, 0])
                cylinder(d = knuckle_d, h = knuckle_h + 0.01);
    }

    // Pin hole along the common axis (y = 12.5, z = 4) through every knuckle
    translate([seg_x(1) - eps, plate_wid/2, knuckle_h * 0.25])
        rotate([0, 90, 0])
            cylinder(d = pin_d, h = (seg_x(5) - seg_x(1)) + 2*eps);
