difference() {
    union() {
        // Outer rim
        cylinder(d = wheel_od, h = wheel_w);
        // Hub (overlaps rim slightly for a clean union)
        translate([0, 0, -0.01])
            cylinder(d = hub_d, h = wheel_w + 0.02);
    }
    // Axle hole through hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = wheel_w + 2 * eps);
    // Radial spokes cut from outer edge inward (evenly spaced, first along +X)
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, i * 360 / spoke_count])
            translate([wheel_od / 2 - 1, -spoke_w / 2, 0])
                cube([(wheel_od / 2 - 1) + eps, spoke_w, wheel_w]);
}
