        difference() {
            cylinder(h = wheel_thickness, r = outer_r);
            translate([0, 0, -cut_extra])
                cylinder(h = wheel_thickness + 2 * cut_extra, r = inner_r);
        }

        // Hub (overlaps rim slightly for a clean union)
        translate([0, 0, -cut_extra])
            cylinder(h = wheel_thickness + 2 * cut_extra, r = hub_r);
    }

    // Axle hole through the hub
    translate([0, 0, -cut_extra])
        cylinder(h = wheel_thickness + 2 * cut_extra, d = axle_hole_d);

    // Spokes, cut from the hub outward to the rim
    for (i = [0 : spoke_count - 1]) {
        rotate([0, 0, spoke_start_angle + i * 360 / spoke_count])
            translate([hub_r - spoke_width / 2, -spoke_width / 2, -cut_extra])
                cube([spoke_width / 2 + inner_r - hub_r,
                      spoke_width,
                      wheel_thickness + 2 * cut_extra]);
