difference() {
    union() {
        // Base plate, centred on origin in X/Y
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments (i = 0, 2, 4)
        for (i = [0 : 2 : 4])
            translate([seg_center(i), plate_wid/2 - 0.01, knuckle_z])
                cylinder(d = knuckle_d, h = 4);
    }

    // Pin hole through every knuckle along the X axis
    for (i = [0 : 2 : 4])
        translate([seg_center(i), plate_wid/2 - 0.01, knuckle_z])
            rotate([0, 90, 0])
                cylinder(d = pin_d, h = knuckle_d + 2*eps, center = true);
}
