knuckle_z   = 3.5;   // knuckle axis height above bed
knuckle_n   = 3;     // number of knuckles (1st, 2nd, 3rd segments)
knuckle_pitch = plate_len / knuckle_n; // 15 mm spacing
knuckle_hole_d = 2;  // pin hole diameter

// ---- Cutting overlap ----
eps = 0.5;           // extension past cut faces

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders, axis along X at y = plate_wid/2
        for (i = [0 : knuckle_n - 1]) {
            x = -plate_len/2 + i * knuckle_pitch;
            translate([x, plate_wid/2, 0])
                cylinder(d = knuckle_d, h = plate_wid/2 + eps);
        }
    }

    // Pin hole through every knuckle along the common axis
    translate([-plate_len/2, plate_wid/2, 0])
        cylinder(d = knuckle_hole_d, h = plate_wid/2 + 2*eps);
}
