// Evenly spaced angles, first point on +X axis
function star_points(outer, inner, points) =
    [for (i = [0 : points - 1])
        concat(
            [outer * cos((i * 360 / points))],
            [outer * sin((i * 360 / points))],
            [inner * cos(((i + 0.5) * 360 / points))],
