difference() {
    // Solid star plate
    linear_extrude(height = plate_t)
        polygon(points = points * 2,
                 hull() = concat(
                     [outer_r * [cos(k * 360 / points), sin(k * 360 / points)] for k in [0 : points - 1]],
                     [inner_r * [cos(k * 360 / points + 180 / points), sin(k * 360 / points + 180 / points)] for k in [0 : points - 1]]
                 ));

