// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 up to part thickness

// ---------------- Parameters ----------------
part_thickness   = 5;     // wheel thickness (Z)
outer_diameter   = 100;   // outer rim diameter
rim_width        = 6;     // rim width (radial)
hub_diameter     = 16;    // hub diameter
axle_hole_d      = 6;     // axle hole diameter
spoke_count      = 5;     // number of spokes
spoke_width      = 4;     // spoke width (tangential)
spoke_start_ang  = 0;     // first spoke along +X axis (degrees)
cut_extra        = 0.5;   // overshoot for clean boolean cuts
$fn              = 128;   // circle resolution

// Derived
rim_inner_d = outer_diameter - 2 * rim_width;   // 88 mm
hub_r       = hub_diameter / 2;
spoke_len   = (outer_diameter / 2) - (hub_r - cut_extra); // radial reach

// ---------------- Model ----------------
difference() {
    union() {
        // Outer rim
        cylinder(d = outer_diameter, h = part_thickness);

        // Hub
        translate([0, 0, 0])
            cylinder(r = hub_r, h = part_thickness);

        // Spokes
        for (i = [0 : spoke_count - 1]) {
            rotate([0, 0, spoke_start_ang + i * 360 / spoke_count])
                translate([0, -spoke_width / 2, 0])
                    cube([spoke_len, spoke_width, part_thickness]);
        }
    }

    // Axle hole through hub centre
    translate([0, 0, -cut_extra])
        cylinder(d = axle_hole_d, h = part_thickness + 2 * cut_extra);
}
